import{z as s,x as l,o as e,c as d,q as t,j as i,D as a,d as B,s as o,S as r,b as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"援助与制度","description":"","frontmatter":{"title":"援助与制度","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/gd-aid-institutions.md","filePath":"econ/gd-aid-institutions.md","lastUpdated":1791063341000}'),m={name:"econ/gd-aid-institutions.md"};function u(c,E,p,h,D,f){const A=l("Mermaid");return e(),d("div",null,[E[2]||(E[2]=t('<h1 id="援助与制度" tabindex="-1">援助与制度 <a class="header-anchor" href="#援助与制度" aria-label="Permalink to &quot;援助与制度&quot;">​</a></h1><div class="epigraph"><p>如果贫穷是资本缺口，援助就该加速收敛；如果贫穷是激励结构的缺口，援助买不来它想买的东西。</p><footer>—— 据 Easterly, &quot;Can Foreign Aid Buy Growth?&quot;, JEP 2003；Rajan and Subramanian, REStud 2008 整理</footer></div><p><a href="/econ/gd-development-micro">上一课</a>把发展的微观证据钉在回报、外部性与三道门上——那是家庭与村庄尺度的干预。往上一级是国家尺度的干预：援助，它试图直接补上资本缺口。本课问两个问题：援助买得到增长吗；若收入由制度决定——主干课的 <a href="/econ/institutions-acemoglu">制度与殖民起源</a> 已给出殖民起源的主通道——援助能否改变制度本身。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>索洛口径下低收入国资本稀缺、边际产出高，资本应当流入，援助应当加速收敛（<a href="/econ/convergence-accounting">收敛与发展核算</a>）；<a href="/econ/lucas-paradox">Lucas 悖论</a>问的正是资本为什么没有大规模流向穷国。<span class="marginnote">「资本缺口」是把穷国想成一台缺零件的机器：钱到位机器就能转。直觉来自资本边际产出递减——穷国资本少，每多一台机器回报更高。但本课要拆的正是这个类比：缺的往往不是零件，而是让零件肯运转的激励。</span>现实更难堪：半个世纪的巨额援助流入与长期停滞并存，跨国收入差距还在扩大。缺口是把链条拆开：援助到增长的每一环——资金到位、项目落地、宏观加总——哪一环断了；以及微观项目有效与宏观净效应为零，能否同时为真。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>跨国证据走了一条迭代路线。Burnside 与 Dollar 2000 用「援助 × 政策」交互项找到条件有效：政策环境好的受援国，援助与增长正相关，这成为援助条件性的实证根基。Rajan 与 Subramanian 2008 换掉这套规格：不依赖交互项、系统检查样本与滞后选择、用不与政策联动的变量做工具，发现援助对增长的稳健正效应不存在——此前的条件有效经不起规格扫描。<span class="marginnote">初学者容易把「稳健性检验」当成走形式。这里的教训是：换样本窗口、换滞后、换工具变量之后原结论消失，说明正效应活在研究者选的规格里，而不是数据里。自由度越大，越容易「碰」出一篇可发表的结论。</span>教训落在设计判别式上：交互项、样本窗口与工具选择的自由度足以制造结论，跨国的援助弹性本来就小到难以辨认。渠道分析补上机制：援助资金流入会推高实际汇率，可贸易部门被挤压，微观资金的直接收益被相对价格效应吃掉一部分；援助替代国内税收，则削弱政府与纳税人的问责纽带。识别工具自身的风险见 <a href="/econ/iv-weak-instruments">工具变量与弱工具</a>。</p>',7)),(e(),i(r,null,{default:a(()=>[o(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20AID%5B%22%E6%8F%B4%E5%8A%A9%E6%B5%81%E5%85%A5%22%5D%20--%3E%20PROJ%5B%22%E9%A1%B9%E7%9B%AE%E4%B8%8E%E5%85%AC%E5%85%B1%E5%93%81%EF%BC%9A%E5%BE%AE%E8%A7%82%E4%B8%BA%E6%AD%A3%22%5D%0A%20%20AID%20--%3E%20FX%5B%22%E5%AE%9E%E9%99%85%E6%B1%87%E7%8E%87%E5%8D%87%E5%80%BC%EF%BC%9A%E5%8F%AF%E8%B4%B8%E6%98%93%E9%83%A8%E9%97%A8%E5%8F%97%E5%8E%8B%22%5D%0A%20%20AID%20--%3E%20TAX%5B%22%E6%9B%BF%E4%BB%A3%E7%A8%8E%E6%94%B6%EF%BC%9A%E9%97%AE%E8%B4%A3%E7%BA%BD%E5%B8%A6%E5%BC%B1%E5%8C%96%22%5D%0A%20%20PROJ%20--%3E%20GROW%7B%22%E5%AE%8F%E8%A7%82%E5%8A%A0%E6%80%BB%EF%BC%9A%E5%87%80%E6%95%88%E5%BA%94%22%7D%0A%20%20FX%20--%3E%20GROW%0A%20%20TAX%20--%3E%20GROW%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=n("h2",{id:"机制",tabindex:"-1"},[B("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=n("p",null,"「缺什么补什么」在制度维度失效，因为制度不是可以购买的设备。AJR 2002 的财富反转补齐了论证：1500 年前后相对富裕的殖民地在今天反而更穷——若地理或人力资本直接决定收入，反转难以解释；若持久的制度变量在殖民时被锚定，反转恰是它的预测。制度是均衡的分布：援助作为外生收入改变统治者与被统治者的谈判结构，与资源诅咒同构，所以在增长维度上「买制度」近乎自我拆台。这也回答了上一课留下的问题：发疫苗、发驱虫药的项目成功与援助宏观无效同时为真——前者的产出不经过激励结构，后者的目标恰恰全部落在激励结构上。层次不同，并不矛盾。",-1)),(e(),i(r,null,{default:a(()=>[o(A,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20RICH%5B%221500%20%E5%B9%B4%E7%9B%B8%E5%AF%B9%E5%AF%8C%E8%A3%95%E7%9A%84%E6%AE%96%E6%B0%91%E5%9C%B0%22%5D%20--%3E%20EXT%5B%22%E6%94%AB%E5%8F%96%E5%9E%8B%E5%88%B6%E5%BA%A6%E8%A2%AB%E9%94%9A%E5%AE%9A%22%5D%0A%20%20LEAN%5B%221500%20%E5%B9%B4%E7%9B%B8%E5%AF%B9%E8%B4%AB%E7%98%A0%E7%9A%84%E6%AE%96%E6%B0%91%E5%9C%B0%22%5D%20--%3E%20INC%5B%22%E5%AE%9A%E5%B1%85%E8%80%85%E5%B8%A6%E6%9D%A5%E8%BE%83%E5%8C%85%E5%AE%B9%E5%88%B6%E5%BA%A6%22%5D%0A%20%20EXT%20--%3E%20POOR%5B%22%E4%BB%8A%E5%A4%A9%E5%8F%8D%E8%80%8C%E6%9B%B4%E7%A9%B7%22%5D%0A%20%20INC%20--%3E%20RICHER%5B%22%E4%BB%8A%E5%A4%A9%E6%9B%B4%E5%AF%8C%22%5D%0A%20%20AID%5B%22%E6%8F%B4%E5%8A%A9%E6%B3%A8%E5%85%A5%E5%A4%96%E7%94%9F%E6%94%B6%E5%85%A5%22%5D%20--%3E%20BARG%5B%22%E6%94%B9%E5%8F%98%E7%BB%9F%E6%B2%BB%E8%80%85%E4%B8%8E%E8%A2%AB%E7%BB%9F%E6%B2%BB%E8%80%85%E7%9A%84%E8%B0%88%E5%88%A4%E7%BB%93%E6%9E%84%22%5D%0A%20%20BARG%20--%3E%20CURSE%5B%22%E4%B8%8E%E8%B5%84%E6%BA%90%E8%AF%85%E5%92%92%E5%90%8C%E6%9E%84%3A%20%E5%88%B6%E5%BA%A6%E9%9A%BE%E6%94%B9%E5%96%84%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">制度像交通规则而不是路灯设备：疫苗、水井是发下去就能用的「路灯」；而「大家都守规则」是所有人预期别人也会守规则时的均衡——给钱改不动预期，预期的均衡就还在原地。援助买设备容易，买预期难。</span></p><p><span class="marginnote">条件性（conditionality）的实证处境比叙事弱得多：政策的可观察性、再谈判与「援助者无法可信地撤出」让条件常落空——Burnside–Dollar 的交互项后来在更大样本中不稳定，是条件性叙事的实证转折。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>「援助宏观无效」不推出「切断援助」：人道救援与公共卫生的微观收益真实存在，本课的结论只针对「援助买增长」这条通道。效应异质与时间尺度未合拢：小国、冲突后国家、长滞后下的效应可能不同，跨国平均把它们抹平。制度内生性的识别争议——殖民者死亡率的排除限制——主干课已经写下，本课不加码也不重审。最后，增长核算的残差仍把制度、<a href="/econ/misallocation-tfp">错配</a>与结构缺口混在一起，援助效应若要被辨认，先要回答「对什么残差」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>条件有效的交互项证据经不起规格扫描；Rajan–Subramanian 之后，援助对增长的稳健效应不被承认。</li><li>渠道拆解：微观项目为正、汇率渠道与问责渠道为负，净效应取决于三者的权重。</li><li>财富反转是制度解释的关键证据：地理直接解释吃力，持久制度变量上位。</li><li>制度是均衡分布不是设备；援助买制度与削弱问责同构。</li><li>微观项目成功与宏观无效同时为真：产出是否经过激励结构是分界。</li><li>出处：Burnside and Dollar, <em>AER</em> 2000；Rajan and Subramanian, <em>REStud</em> 2008；Acemoglu, Johnson and Robinson, <em>QJE</em> 2002；Easterly, <em>JEP</em> 2003。</li></ul>',6))])}const F=s(m,[["render",u]]);export{_ as __pageData,F as default};
